var Roblox=Roblox||{};Roblox.Lang=Roblox.Lang||{};Roblox.Lang['Feature.AccountSettings']={"Action.Add":"Dodaj","Action.AllowAccessContactsV3":"Dostęp do kontaktów na urządzeniu","Action.Cancel":"Anuluj","Action.Delete":"Usuń","Action.Done":"Gotowe","Action.EditPaymentMethod":"Edytuj formę płatności","Action.Join":"Dołącz","Action.Next":"Dalej","Action.Remove":"Usuń","Action.Report":"Zgłoś","Action.Save":"Zapisz","Action.Show":"Pokaż","Action.Subscribe":"Subskrybuj","Description.AccountEmailRevertEmail.From":"{escapeLiteralStart}Resetowanie adresu e-mail na platformie Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.AccountEmailRevertEmail.HtmlBody.V2":"Cześć, {username}!{lineBreak}{lineBreak}Zauważyliśmy zmianę twojego adresu e-mail z {oldEmailAddress} na {newEmailAddress}. Jeśli zmiana ta została dokonana przez ciebie, możesz zignorować tę wiadomość e-mail.{lineBreak}{lineBreak}Jeśli nie stało się to na twoją prośbę lub nastąpiło na skutek pomyłki, kliknij ten link, aby przywrócić poprzedni adres e-mail: {aTagWithHref}{revertAccountEmailLinkWithTicket}{hrefEnd}{revertAccountEmailLink}{aTagEnd}. Aby zapewnić bezpieczeństwo konta, pojawi się prośba o wprowadzenie nowego hasła.{lineBreak}{lineBreak}Nie odpowiadaj na tę wiadomość. Jeśli masz jakieś pytania, odwiedź nasze <a target=\"_blank\" href=\"{accountHelpLink}\">centrum pomocy</a>.","Description.AccountEmailRevertEmail.PlainBody.V2":"Cześć, {username}!{lineBreak}{lineBreak}Zauważyliśmy zmianę twojego adresu e-mail z {oldEmailAddress} na {newEmailAddress}. Jeśli zmiana ta została dokonana przez ciebie, możesz zignorować tę wiadomość e-mail.{lineBreak}{lineBreak}Jeśli nie stało się to na twoją prośbę lub nastąpiło na skutek pomyłki, kliknij ten link, aby przywrócić poprzedni adres e-mail: {revertAccountEmailLink}. Aby zapewnić bezpieczeństwo konta, pojawi się prośba o wprowadzenie nowego hasła.{lineBreak}{lineBreak}Nie odpowiadaj na tę wiadomość. Jeśli masz jakieś pytania, odwiedź nasze centrum pomocy ({accountHelpLink}).","Description.AccountEmailRevertEmail.Subject":"Resetowanie adresu e-mail na platformie Roblox","Description.AllowAccessContactsV2":"Opcje zarządzania dostępem do kontaktów znajdziesz w ustawieniach prywatności konta na urządzeniach mobilnych","Description.PasskeySkips2sv":"Za każdym razem, gdy logujesz się za pomocą klucza dostępu, pomijasz wybraną metodę weryfikacji dwuetapowej. Dzieje się tak, ponieważ klucze dostępu są bardzo bezpieczne i pomagają zweryfikować, czy jesteś w posiadaniu fizycznego urządzenia.","Description.Subscriptions.NoActive":"Nie masz żadnych aktywnych subskrypcji","Description.TranslationDisclaimer":"Tłumaczenia są generowane przez platformę Roblox i mogą zawierać błędy. {linkStart}Dowiedz się więcej{linkEnd}","Description.TwoStepVerification":"Dodatkowa warstwa zabezpieczeń konta {lineBreaks}Oprócz hasła dodaj kolejną warstwę zabezpieczeń konta za pomocą weryfikacji dwuetapowej podczas logowania, odzyskiwania konta i transakcji o wysokiej wartości. Uwaga: jednocześnie można włączyć tylko jedną z poniższych opcji.","Description.UsernameChangeEmail.From":"{escapeLiteralStart}Zmiana nazwy użytkownika platformy Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.UsernameChangeEmail.Message":"Prośba o zmianę nazwy użytkownika została przetworzona. Twoja nazwa użytkownika została zmieniona z {oldUsername} na {newUsername}. Jeśli zmiana nazwy użytkownika nie nastąpiła na twoją prośbę, zapoznaj się z treścią pomocy dotyczącej konta w naszym {startLink}centrum pomocy{endLink}. Nie odpowiadaj bezpośrednio na tę wiadomość e-mail, ponieważ odpowiedzi przesyłane na ten adres nie są odbierane.","Description.UsernameChangeEmail.Subject":"Zmiana nazwy użytkownika platformy Roblox","Description.VerificationEmail.Body.Over13.V2":"{paragraphStart}Cześć!{paragraphEnd}{paragraphStart}Dziękujemy za podanie adresu e-mail w celu zabezpieczenia konta {emphasisStart}{username}{emphasisEnd}.{paragraphEnd}{paragraphStart}Jeśli ta prośba została przesłana przez ciebie, kliknij przycisk poniżej, aby zakończyć proces weryfikacji:{paragraphEnd}","Description.VerificationEmail.Body.Under13.V2":"{paragraphStart}Cześć!{paragraphEnd}{paragraphStart}Twoje dziecko utworzyło konto {emphasisStart}{username}{emphasisEnd} na platformie Roblox, internetowej platformie rozrywkowej, która umożliwia dzieciom wymyślanie oraz tworzenie imersyjnych, tworzonych przez użytkowników, trójwymiarowych światów i wspólną zabawę w nich.{paragraphEnd}{paragraphStart}Twoje dziecko podało nam nazwę użytkownika, datę urodzenia, oraz adres e-mail rodzica. Prosimy o potwierdzenie poprawności adresu e-mail przez {emphasisStart}kliknięcie poniższego przycisku, co umożliwi ukończenie procesu weryfikacji{emphasisEnd}. Niezależnie od tego, czy zweryfikujesz swój adres e-mail, czy nie, dziecko nadal będzie mogło zachować swoje konto i rozmawiać na czacie z innymi osobami.{paragraphEnd}{paragraphStart}Klikając „Zgadzam się, zweryfikuj adres e-mail”, potwierdzasz również, że (a) ty i twoje dziecko wyrażacie zgodę na {aTagStartWithHref}{termsOfServiceLink}{hrefEnd}Warunki użytkowania platformy Roblox{aTagEnd}, w tym na arbitraż, oraz (b) będziesz nadzorować i ponosić wyłączną odpowiedzialność za korzystanie przez twoje dziecko z platformy Roblox.{paragraphEnd}","Description.VerificationEmail.Body.Under13.V4":"{paragraphStart}Cześć!{paragraphEnd}{paragraphStart}Ta wiadomość e-mail została do ciebie wysłana w celu powiadomienia o koncie twojego dziecka na platformie Roblox ({emphasisStart}{username}{emphasisEnd}) oraz o możliwości weryfikacji adresu e-mail w celu skonfigurowania dodatkowych zabezpieczeń i kontroli rodzicielskiej na koncie dziecka.{paragraphEnd}{paragraphStart}Gdy twoje dziecko zakładało konto na platformie Roblox, zgromadziliśmy następujące informacje: nazwę użytkownika, hasło, datę urodzenia i płeć. Ty lub twoje dziecko dodaliście ostatnio do konta adres e-mail rodzica. Prosimy o potwierdzenie, że ten adres e-mail jest poprawny poprzez {emphasisStart}kliknięcie poniższego przycisku:{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Over13.V2":"{paragraphStart}Dziękujemy.{lineBreak}{emphasisStart}Zespół Roblox{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Under13.V2":"{paragraphStart}Ustawienia bezpieczeństwa i kontroli rodzicielskiej dla konta dziecka na platformie Roblox można skonfigurować na stronie {aTagStartWithHref}{accountSettingsLink}{hrefEnd}{accountSettingsLink}{aTagEnd}.{paragraphEnd}{paragraphStart}{emphasisStart}Roblox – Przewodnik dla rodziców{emphasisEnd}{paragraphEnd}{paragraphStart}Zalecamy zapoznanie się z Przewodnikiem dla rodziców, aby lepiej poznać naszą platformę i znaleźć pomocne wskazówki dotyczące zapewnienia dzieciom wspaniałej rozrywki na platformie Roblox: {aTagStartWithHref}{parentalPageLink}{hrefEnd}{parentalPageLink}{aTagEnd}{paragraphEnd}{paragraphStart}{emphasisStart}Prywatność{emphasisEnd}{paragraphEnd}{paragraphStart}Konto dziecka można w każdej chwili usunąć, kontaktując się z działem wsparcia klientów pod adresem {aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}. Twój adres e-mail nie będzie wykorzystywany do żadnych innych celów, ujawniany stronom trzecim ani łączony z innymi danymi osobowymi otrzymanymi od twojego dziecka. Więcej informacji można znaleźć w naszej Polityce prywatności tutaj: {aTagStartWithHref}{privacyPageLink}{hrefEnd}{privacyPageLink}{aTagEnd}.{paragraphEnd}{paragraphStart}Dziękujemy.{lineBreak}{emphasisStart}Zespół Roblox{emphasisEnd}{paragraphEnd}","Description.VerificationEmail.BodyLower.Under13.V4":"{paragraphStart}Po zweryfikowaniu swojego adresu e-mail uzyskasz możliwość zresetowania hasła dziecka (jeśli to będzie konieczne), otrzymywania informacji dotyczących działań na koncie dziecka oraz zmiany ustawień bezpieczeństwa i kontroli rodzicielskiej tego konta na platformie Roblox pod adresem https://www.roblox.com/my/account#!.{paragraphEnd}{paragraphStart}Jeśli nie zweryfikujesz swojego adresu e-mail, twoje dziecko nadal będzie mogło korzystać ze swojego konta, grać na platformie Roblox i mieć dostęp do większości funkcji, w tym filtrowanego czatu tekstowego.{paragraphEnd}{paragraphStart}Twój adres e-mail nie będzie wykorzystywany do żadnych innych celów, ujawniany stronom trzecim ani łączony z innymi danymi osobowymi otrzymanymi od dziecka. Poza adresem e-mail rodzica nie gromadzimy, nie wykorzystujemy ani nie ujawniamy danych osobowych użytkowników będących dziećmi.{paragraphEnd}{paragraphStart}Więcej informacji można znaleźć w naszej Polityce prywatności tutaj: https://www.roblox.com/info/privacy.{paragraphEnd}{paragraphStart}{emphasisStart}Roblox – Przewodnik dla rodziców{emphasisEnd}{paragraphEnd}{paragraphStart}Roblox to internetowa platforma rozrywkowa, która umożliwia dzieciom wymyślanie oraz tworzenie imersyjnych, tworzonych przez użytkowników, trójwymiarowych światów i wspólną zabawę w nich.{paragraphEnd}{paragraphStart}Zalecamy zapoznanie się z Przewodnikiem dla rodziców, aby lepiej poznać naszą platformę i znaleźć pomocne wskazówki dotyczące zapewnienia dzieciom wspaniałej rozrywki na platformie Roblox: https://www.roblox.com/info/parents{paragraphEnd}{paragraphStart}{emphasisStart}Inne ważne informacje{emphasisEnd}{paragraphEnd}{paragraphStart}Możesz odmówić zgody na korzystanie przez dziecko z platformy Roblox, zażądać usunięcia konta dziecka i/lub w dowolnym momencie zażądać usunięcia swojego adresu e-mail. Aby podjąć którekolwiek z tych działań, należy skontaktować się z działem wsparcia klientów pod adresem https://www.roblox.com/support.{paragraphEnd}{paragraphStart}Zezwalając dziecku na zachowanie konta na platformie Roblox, potwierdzasz, że (a) ty i twoje dziecko akceptujecie {aTagStartWithHref}{termsOfServiceLink}{hrefEnd}Warunki użytkowania platformy Roblox{aTagEnd}, w tym arbitraż, oraz (b) będziesz nadzorować i ponosić wyłączną odpowiedzialność za korzystanie przez twoje dziecko z platformy Roblox.{paragraphEnd}{paragraphStart}Dziękujemy.{paragraphEnd}{paragraphStart}Zespół Roblox{paragraphEnd}","Description.VerificationEmail.ButtonText.Over13.V2":"Zweryfikuj adres e-mail","Description.VerificationEmail.ButtonText.Under13.V2":"Zgadzam się, zweryfikuj adres e-mail","Description.VerificationEmail.Footer.Over13.V2":"Nie odpowiadaj bezpośrednio na tę wiadomość e-mail. Otrzymujesz tę wiadomość e-mail, ponieważ podjęto próbę zweryfikowania twojego konta Roblox za pomocą adresu e-mail. Jeśli ta prośba nie pochodziła od ciebie, zignoruj tę wiadomość.","Description.VerificationEmail.Footer.Under13.V2":"Nie odpowiadaj bezpośrednio na tę wiadomość e-mail. Otrzymujesz tę wiadomość e-mail, ponieważ podjęto próbę zweryfikowania twojego konta Roblox za pomocą adresu e-mail. Jeśli ta prośba nie pochodziła od ciebie, zignoruj tę wiadomość.","Description.VerificationEmail.From.Over13":"{escapeLiteratStart}Weryfikacja adresu e-mail na platformie Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.VerificationEmail.From.Under13":"{escapeLiteratStart}Uwierzytelnienie konta Roblox{escapeLiteralEnd} {fromEmailAddress}","Description.VerificationEmail.Header.Over13.V2":"Weryfikacja adresu e-mail na platformie Roblox","Description.VerificationEmail.Header.Under13.V2":"Weryfikacja adresu e-mail na platformie Roblox","Description.VerificationEmail.HtmlBody.Over13":"Szanowny użytkowniku platformy Roblox!{lineBreak}{lineBreak}Cieszymy się z twojej decyzji o zabezpieczeniu konta {username} przez podanie adresu e-mail.{lineBreak}Dzięki weryfikacji adresu e-mail powiązanego z kontem Roblox zwiększasz poziom bezpieczeństwa konta.{lineBreak}Kliknij poniższy przycisk, aby zakończyć proces weryfikacji.{lineBreak}{lineBreak}{aTagStartWithHref}{verificationLink}{targetBlank}{buttonStart}Zweryfikuj adres e-mail{buttonEnd}{aTagEnd}","Description.VerificationEmail.HtmlBody.Under13":"Cześć{lineBreak}{lineBreak}Twoje dziecko utworzyło konto {boldTagStart}{username}{boldTagEnd} na platformie Roblox, internetowej platformie rozrywkowej, która umożliwia dzieciom wymyślanie oraz tworzenie imersyjnych, tworzonych przez użytkowników, trójwymiarowych światów i wspólną zabawę w nich. Nasza platforma zapewnia darmowe narzędzie deweloperskie o nazwie „Roblox Studio”, umożliwiające użytkownikom tworzenie wszystkiego, co podpowie im wyobraźnia – od prostych projektów budowanych metodą przeciągania i upuszczania po złożone gry wieloosobowe. Miliony dzieci skorzystało już z platformy Roblox, aby zrealizować marzenia o stworzeniu wspaniałego parku rozrywki, o karierze kierowcy rajdowego czy gwiazdy wybiegów, albo po prostu o zbudowaniu wymarzonego domu i zaproszeniu do niego znajomych.{lineBreak}{lineBreak}Kontaktujemy się z tobą, aby cię poinformować, że twoje dziecko podało nam nazwę użytkownika, datę urodzenia, oraz adres e-mail rodzica. Adres e-mail rodzica służy wyłącznie do zarządzania kontem, resetowania hasła, jeśli dziecko go zapomni, oraz do powiadamiania rodziców o zmianach w dostępie do konta dziecka. W celu weryfikacji adresu e-mail kliknij poniższy przycisk: {lineBreak}{lineBreak}{aTagStartWithHref}{verificationLink}{hrefEnd}{buttonStart}Zweryfikuj adres e-mail{buttonEnd}{aTagEnd}{lineBreak}{lineBreak}{boldTagStart}Informacje o platformie Roblox{boldTagEnd}{lineBreak}{lineBreak}Powstaniu platformy Roblox przyświecał cel stworzenia radosnego, rodzinnego środowiska. Stale udoskonalamy nasze zabezpieczenia i współpracujemy z ekspertami ds. bezpieczeństwa cyfrowego, aby zapewnić wszystkim graczom bezpieczne, komfortowe miejsce do zabawy, rozmów na czacie i współpracy nad kreatywnymi projektami. Zalecamy zapoznanie się z Przewodnikiem dla rodziców, aby lepiej poznać naszą platformę i znaleźć pomocne wskazówki dotyczące zapewnienia dzieciom wspaniałej rozrywki na platformie Roblox: {aTagStartWithHref}{parentalPageLink}{hrefEnd}{parentalPageLink}{aTagEnd}{lineBreak}{lineBreak}Platforma Roblox oferuje również ustawienia {boldTagStart}kontroli rodzicielskiej{boldTagEnd}. Rodzice mogą aktywować rodzicielski kod PIN, aby zmieniać ustawienia komunikacji i czatu dziecka. Ustawienia te można znaleźć, odwiedzając karty zabezpieczeń i prywatności w ustawieniach konta po zalogowaniu się na konto dziecka.{lineBreak}{lineBreak}Aby dodać kod PIN rodzica, odwiedź: {aTagStartWithHref}{accountSecurityLink}{hrefEnd}{accountSecurityLink}{aTagEnd}.{lineBreak}{lineBreak}Aby zmienić ustawienia czatu, odwiedź: {aTagStartWithHref}{accountPrivacyLink}{hrefEnd}{accountPrivacyLink}{aTagEnd}.{lineBreak}{lineBreak}{boldTagStart}Prywatność{boldTagEnd}{lineBreak}{lineBreak}Konto dziecka można usunąć, kontaktując się z działem wsparcia klientów pod adresem {aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}. Twój adres e-mail nie będzie wykorzystywany do żadnych innych celów, ujawniany stronom trzecim ani łączony z innymi danymi osobowymi otrzymanymi od twojego dziecka. Więcej informacji można znaleźć w naszej Polityce prywatności tutaj: {aTagStartWithHref}{privacyPageLink}{hrefEnd}{privacyPageLink}{aTagEnd}.{lineBreak}{lineBreak}{lineBreak}Dziękujemy.{lineBreak}{lineBreak}Zespół Roblox{lineBreak}{lineBreak} Nie odpowiadaj bezpośrednio na tę wiadomość e-mail. {lineBreak}{lineBreak} {aTagStartWithHref}{robloxWebsiteLink}{hrefEnd}{robloxWebsiteLink}{aTagEnd} {lineBreak}{lineBreak} {aTagStartWithHref}{supportPageLink}{hrefEnd}{supportPageLink}{aTagEnd}","Description.VerificationEmail.Links.Over13.V2":"{aTagStartWithHref}{AccountSafetyArticleLink}{hrefEnd}Bezpieczeństwo konta{aTagEnd} | {aTagStartWithHref}{supportPageLink}{hrefEnd}Wsparcie{aTagEnd}","Description.VerificationEmail.Links.Under13.V2":"{aTagStartWithHref}{parentalPageLink}{hrefEnd}Dla rodziców{aTagEnd} | {aTagStartWithHref}{supportPageLink}{hrefEnd}Wsparcie{aTagEnd}","Description.VerificationEmail.PlainBody.Over13":"Szanowny użytkowniku platformy Roblox!{lineBreak}{lineBreak}Cieszymy się z twojej decyzji o zabezpieczeniu konta {username} przez podanie adresu e-mail.{lineBreak}Dzięki weryfikacji adresu e-mail powiązanego z kontem Roblox zwiększasz poziom bezpieczeństwa konta.{lineBreak}Kliknij poniższy link, aby zakończyć proces weryfikacji{lineBreak}{verificationLink}.\n","Description.VerificationEmail.Subject.Over13":"Weryfikacja adresu e-mail na platformie Roblox","Description.VerificationEmail.Subject.Over13.V2":"Weryfikacja adresu e-mail na platformie Roblox: {username}","Description.VerificationEmail.Subject.Under13":"Uwierzytelnienie konta Roblox","Description.VerificationEmail.Subject.Under13.V2":"Weryfikacja adresu e-mail na platformie Roblox: {username}","Description.VerificationEmail.Subject.Under13.V4":"Weryfikacja adresu e-mail rodzica na platformie Roblox: {username}","Heading.Billing":"Rozliczenia","Heading.Dialog.DisableUpdateFriendsAboutMyActivity":"Włączono powiadomienia o aktywnościach znajomych","Heading.Dialog.ShareCurrentExperiencesWithFriends":"Udostępniasz teraz znajomym bieżący projekt","Heading.LoginMethods":"Metody logowania","Heading.PageTitle":"Ustawienia","Heading.PasskeyCreated":"Utworzono klucz dostępu","Heading.PrivateServers":"Serwery prywatne","Heading.Subscriptions.Active":"Aktywne ({activeNumber})","Label.CameraNotAvailable":"Kamera nie jest dostępna na niektórych urządzeniach.","Label.CameraNotSupported":"Kamera nie jest dostępna na niektórych urządzeniach. {linkStart}Więcej informacji{linkEnd}","Label.Cancel":"Anuluj","Label.CreatedBy":"Od: {creator}","Label.DropDown.No":"Nie","Label.DropDown.Yes":"Tak","Label.Email":"Adres e-mail:","Label.Enable":"Włącz","Label.Manage":"Zarządzaj","Label.Passkey":"Klucz dostępu:","Label.Password":"Hasło:","Label.Phone":"Numer telefonu:","Label.Repeat":"Powtarzaj","Label.ToolTip.UpdateFriendsAboutMyActivity":"Jeśli wybierzesz „Tak”, twoi znajomi będą mogli otrzymywać powiadomienia o twoich ostatnich aktywnościach w projektach.","Label.UpdateFriendsAboutMyActivity":"Powiadamiać znajomych o moich aktywnościach?","Label.Username":"Nazwa użytkownika:","MessageInvalidEmail":"Nieprawidłowy adres e-mail","MessagePinLockedError":"PIN jest zablokowany.","MessageSettingsUpdateSuccess":"Ustawienia zostały zaktualizowane.","MessageUnknownError":"Wystąpił nieznany błąd.","Response.Dialog.DisableUpdateFriendsAboutMyActivity":"Ponieważ nie udostępniasz już znajomym bieżącego projektu, twoi znajomi nie będą też otrzymywać powiadomień o twoich aktywnościach.","Response.Dialog.ShareCurrentExperiencesWithFriends":"Ponieważ powiadomienia o aktywnościach znajomych są teraz włączone, Twoi znajomi również będą mogli zobaczyć Twoją bieżącą grę i dołączyć do Ciebie.","Response.VerificationError":"Podczas weryfikacji wystąpił błąd systemu."};Roblox.Lang['AccountSettingsResources']=Roblox.Lang['Feature.AccountSettings'];

