var Roblox=Roblox||{};Roblox.Lang=Roblox.Lang||{};Roblox.Lang['Feature.Tracking']={"Action.RequestData":"Poproś o swoje dane","Action.SavePreferences":"Zapisz preferencje","Action.SetCookieOptions":"Ustaw opcje plików cookie","Description._cfduid":"Zespół wsparcia klienta Zendesk","Description.CookieBannerContent":"Używamy plików cookie do personalizowania i usprawniania naszej witryny internetowej. Aby uzyskać więcej informacji o naszych praktykach dotyczących gromadzenia danych, odwiedź stronę {privacyPolicyLink}. Klikając przycisk „Akceptuj”, wyrażasz zgodę na używanie plików cookie w celach wymienionych na liście ustawień. Aby zapoznać się z pełną listą firm używających tych plików cookie oraz innych technologii oraz zdecydować, czy mogą one być wykorzystywane na twoim urządzeniu, skorzystaj z naszego narzędzia do zarządzania plikami cookie. Tę wiadomość zobaczysz tylko raz, ale preferencje możesz zawsze zmienić w narzędziu do zarządzania plikami cookie.","Description.CookiePreferenceLink":"Ustaw preferencje dotyczące plików cookie","Description.CookieT":"Plik cookie tokenu uwierzytelniania użytkownika","Description.DataCollected":"Wrażliwe: informacje finansowe\n","Description.DataRetention":"Tak długo, jak jest to konieczne do zaspokojenia potrzeby biznesowej lub zgodnie z wymogami prawa.","Description.DataSharing":"Firmom zewnętrznym są udostępniane dane zbiorcze, dane anonimowe, dane osobowe oraz dane wrażliwe.","Description.DataUse":"Zamieszczanie reklam, ukierunkowywanie reklam, analiza/pomiary, dostosowywanie treści, monitorowanie na wielu urządzeniach, optymalizacja","Description.GAReadMore":"Więcej informacji: {googleAnalyticsLink}","Description.GoogleAnalyticsPurpose":"Narzędzie Google Analytics dostarcza firmom informacji na temat ruchu w ich witrynach oraz skuteczności marketingowej. Pozwala określić właściwe słowa kluczowe, ukierunkować strategię na najlepsze rynki oraz angażować i konwertować więcej klientów.","Description.GuestData":"Tryb gościa nie jest już używany","Description.HasGmid":"Uwierzytelnianie","Description.HelpCenterSession":"Ustawiane na stronie en.help.roblox.com","Description.IclVisitorLangJs":"Ustawienie języka ze strony corp.roblox.com","Description.InformationCollection":"Chcemy zachować przejrzystość w kwestii gromadzenia i wykorzystywania danych przez nas oraz naszych partnerów, aby użytkownicy mogli w jak najlepszy sposób kontrolować swoje dane osobowe. Więcej informacji znajdziesz w naszej polityce prywatności.","Description.InformationCollection2":"Wykorzystujemy te informacje w celu poprawy wydajności naszej witryny oraz wrażeń odwiedzających ją użytkowników. Obejmuje to poprawę wyników wyszukiwania, wyświetlanie trafniejszej zawartości i materiałów promocyjnych, lepszą komunikację oraz większą wydajność.","Description.InformationPartnerCollection":"Współpracujemy z poniższymi firmami, aby poprawić twoje wrażenia na platformie Roblox. Firmy te mogą używać plików cookie i innych mechazmów do monitorowania statystyk użytkowania w naszej witrynie internetowej. Możesz cofnąć zgodę na gromadzenie informacji, ustawiając przełącznik analityki w pozycji wyłączenia.","Description.PrivacyPolicy":"Polityka prywatności","Description.RBXEventTrackerV2":"Testy A/B","Description.RBXIDCHECK":"Plik cookie umożliwiający ominięcie uwierzytelniania dwuetapowego w tej przeglądarce","Description.RBXImageCache":"Uwierzytelnianie","Description.RbxIp2":"Bezpieczeństwo: plik cookie kontroli przeciwfloodingowej","Description.RBXSource":"Analityka: w celu pozyskiwania użytkowników i przypisywania reklam/źródła","Description.RBXViralAcquisition":"Analityka: w celu pozyskiwania użytkowników za pomocą linków z mediów społecznościowych","Description.ROBLOSECURITY":"Plik cookie, dzięki któremu użytkownik pozostaje zalogowany","Description.Undisclosed":"Nie ujawniono","Description.WpmlBrowserRedirectTest":"Test przekierowania przeglądarki","Heading.AnalyticsCookies":"Analityczne pliki cookie","Heading.CompanyCollection":"Jakie dane gromadzi ta firma?","Heading.CookieSettings":"Opcje plików cookie","Heading.EssentialCookies":"Niezbędne pliki cookie","Heading.GoogleAnalytics":"Google Analytics","Heading.GoogleAnalyticsPurpose":"Do czego służy narzędzie Google Analytics?","Heading.InformationCollection":"Informacje, które gromadzimy na twój temat","Heading.InformationCollection2":"Informacje, które gromadzimy","Heading.InformationPartnerCollection":"Informacje gromadzone przez naszych partnerów","Label.DataCollected":"Gromadzone dane","Label.DataRetention":"Retencja danych\n","Label.DataSharing":"Udostępnianie danych","Label.DataStorage":"Przechowywanie danych","Label.DataUse":"Wykorzystanie danych","Label.OwnedBy":"Właściciel","Label.Website":"Witryna internetowa"};Roblox.Lang['TrackingResources']=Roblox.Lang['Feature.Tracking'];

